{
  "id": "csv-to-airtable-workflow",
  "name": "CSV to Airtable Import",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Manual Trigger",
      "type": "n8n-nodes-base.manualTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {}
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "Read CSV File",
      "type": "n8n-nodes-base.readWriteFile",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "operation": "read",
        "filePath": "/path/to/input.csv",
        "options": {
          "encoding": "utf-8"
        }
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Parse CSV",
      "type": "n8n-nodes-base.code",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "mode": "runOnceForAllItems",
        "jsCode": "const csv = items[0].json.data;\nconst lines = csv.trim().split('\\n');\nconst headers = lines[0].split(',').map(h => h.trim());\nconst rows = lines.slice(1).map(line => {\n  const values = line.split(',').map(v => v.trim());\n  const obj = {};\n  headers.forEach((h, i) => obj[h] = values[i]);\n  return obj;\n});\nreturn rows.map(row => ({ json: row }));"
      }
    },
    {
      "id": "d4e5f6a7-b8c9-0123-def0-456789012345",
      "name": "Split Rows",
      "type": "n8n-nodes-base.splitOut",
      "typeVersion": 1,
      "position": [1000, 300],
      "parameters": {
        "fieldToSplitOut": "json",
        "options": {}
      }
    },
    {
      "id": "e5f6a7b8-c9d0-1234-ef01-567890123456",
      "name": "Create Airtable Record",
      "type": "n8n-nodes-base.airtable",
      "typeVersion": 1,
      "position": [1250, 300],
      "parameters": {
        "operation": "create",
        "baseId": "YOUR_BASE_ID",
        "tableId": "YOUR_TABLE_ID",
        "columns": {
          "mappingMode": "defineBelow",
          "value": {}
        },
        "options": {}
      }
    }
  ],
  "connections": {
    "Manual Trigger": {
      "main": [[{ "node": "Read CSV File", "type": "main", "index": 0 }]]
    },
    "Read CSV File": {
      "main": [[{ "node": "Parse CSV", "type": "main", "index": 0 }]]
    },
    "Parse CSV": {
      "main": [[{ "node": "Split Rows", "type": "main", "index": 0 }]]
    },
    "Split Rows": {
      "main": [[{ "node": "Create Airtable Record", "type": "main", "index": 0 }]]
    }
  }
}

