{
  "id": "daily-airtable-export-email",
  "name": "Daily Airtable Export to Email",
  "nodes": [
    {
      "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
      "name": "Daily Midnight Trigger",
      "type": "n8n-nodes-base.scheduleTrigger",
      "typeVersion": 1,
      "position": [250, 300],
      "parameters": {
        "triggerTimes": {
          "item": [
            {
              "hour": 0,
              "minute": 0
            }
          ]
        }
      }
    },
    {
      "id": "b2c3d4e5-f6a7-8901-bcde-f23456789012",
      "name": "Get Airtable Records",
      "type": "n8n-nodes-base.airtable",
      "typeVersion": 1,
      "position": [500, 300],
      "parameters": {
        "operation": "getAll",
        "baseId": "YOUR_BASE_ID",
        "tableId": "YOUR_TABLE_ID",
        "options": {}
      }
    },
    {
      "id": "c3d4e5f6-a7b8-9012-cdef-345678901234",
      "name": "Format as CSV",
      "type": "n8n-nodes-base.code",
      "typeVersion": 1,
      "position": [750, 300],
      "parameters": {
        "language": "javascript",
        "code": "const records = items[0].json;\nif (!records || records.length === 0) {\n  return [{ json: { csv: '' }, binary: {} }];\n}\n\nconst headers = Object.keys(records[0].fields || records[0]);\nconst rows = records.map(r => {\n  const fields = r.fields || r;\n  return headers.map(h => JSON.stringify(fields[h] ?? '')).join(',');\n});\nconst csv = [headers.join(','), ...rows].join('\\n');\n\nreturn [{\n  json: { csv },\n  binary: {\n    data: {\n      data: Buffer.from(csv, 'utf-8'),\n      mimeType: 'text/csv',\n      fileName: `airtable-export-${new Date().toISOString().split('T')[0]}.csv`\n    }\n  }\n}];"
      }
    },
    {
      "id": "d4e5f6a7-b8c9-0123-def0-456789012345",
      "name": "Send Email with Attachment",
      "type": "n8n-nodes-base.emailSend",
      "typeVersion": 1,
      "position": [1000, 300],
      "parameters": {
        "fromEmail": "sender@example.com",
        "toEmail": "recipient@example.com",
        "subject": "Daily Airtable Export - {{ $now.format('YYYY-MM-DD') }}",
        "text": "Please find attached the daily Airtable export.",
        "options": {
          "attachments": [
            {
              "binaryPropertyName": "data"
            }
          ]
        }
      }
    }
  ],
  "connections": {
    "Daily Midnight Trigger": {
      "main": [[{ "node": "Get Airtable Records", "type": "main", "index": 0 }]]
    },
    "Get Airtable Records": {
      "main": [[{ "node": "Format as CSV", "type": "main", "index": 0 }]]
    },
    "Format as CSV": {
      "main": [[{ "node": "Send Email with Attachment", "type": "main", "index": 0 }]]
    }
  }
}

